.box {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid black;
}

h2 { color: red; }
#main { color: blue; }
.title { color: green; }

.box {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 300px;
}

.a {
  position: absolute;
  z-index: 1;
}
.b {
  position: absolute;
  z-index: 5;
}

.btn {
  background-color: navy;
  transition: background-color 0.3s ease;
}
.btn:hover {
  background-color: teal;
}
